public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.size() == 0) {
        return 0;
    }

    int maxLength = 0;
    for (int i = 0; i < strings.size(); i++) {
        String str = strings.get(i);
        String reverseStr = new StringBuilder(str).reverse().toString();

        if (reverseStr.length() > maxLength) {
            maxLength = reverseStr.length();
        }

        int len = str.length();
        for (int j = 1; j < len; j++) {
            String subStr1 = str.substring(j);
            String subStr2 = str.substring(0, j);

            if (str.contains(subStr1) || str.contains(subStr2)) {
                continue;
            }

            if (reverseStr.contains(subStr1) || reverseStr.contains(subStr2)) {
                if (reverseStr.length() > maxLength) {
                    maxLength = reverseStr.length();
                }
            }
        }
    }

    return maxLength;
}
