public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                if (isValidDeposit(grid, i, j)) {
                    count++;
                }
            }
        }
    }
    return count;
}

private static boolean isValidDeposit(char[][] grid, int x, int y) {
    if (x < 0 || y < 0 || x >= grid.length || y >= grid[x].length || grid[x][y] != '@') {
        return false;
    }
    grid[x][y] = '*'; // Mark as visited
    boolean isDeposited = true;
    for (int dx = -1; dx <= 1; dx++) {
        for (int dy = -1; dy <= 1; dy++) {
            if (dx == 0 && dy == 0) continue;
            if (!isValidDeposit(grid, x + dx, y + dy)) {
                isDeposited = false;
                break;
            }
        }
        if (!isDeposited) break;
    }
    return isDeposited;
}
```
