public static int countOilDeposits(char[][] grid) {
    int rowCount = grid.length;
    int colCount = grid[0].length;
    boolean[][] visited = new boolean[rowCount][colCount];
    int depositCount = 0;

    for (int i = 0; i < rowCount; i++) {
        for (int j = 0; j < colCount; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                // Depth-first search to count oil deposits
                visited[i][j] = true;
                depositCount++;
                dfs(grid, i, j, visited);
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, int x, int y, boolean[][] visited) {
    int rows = grid.length;
    int cols = grid[0].length;

    // Check cells right, left, up, and down
    int[][] directions = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};
    for (int[] dir : directions) {
        int nx = x + dir[0];
        int ny = y + dir[1];

        if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && grid[nx][ny] == '@' && !visited[nx][ny]) {
            visited[nx][ny] = true;
            dfs(grid, nx, ny, visited);
        }
    }
}
