public static int countOilDeposits(char[][] grid) {
    Set<String> visited = new HashSet<>();
    int count = 0;

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@' && !visited.contains generateHash(i, j, grid)) {
                markVisited(i, j, grid);
                explore(i, j, grid, visited);
                count++;
            }
        }
    }

    return count;
}

private static void markVisited(int row, int col, char[][] grid) {
    visited.add(generateHash(row, col, grid));
}

private static void explore(int row, int col, char[][] grid, Set<String> visited) {
    if (row < 0 || col < 0 || row >= grid.length || col >= grid[row].length || grid[row][col] != '@' || visited.contains(generateHash(row, col, grid))) {
        return;
    }

    markVisited(row, col, grid);
    explore(row + 1, col, grid, visited); // Down
    explore(row - 1, col, grid, visited); // Up
    explore(row, col + 1, grid, visited); // Right
    explore(row, col - 1, grid, visited); // Left
}

private static String generateHash(int row, int col, char[][] grid) {
    StringBuilder sb = new StringBuilder();
    sb.append(row);
    sb.append(col);
    sb.append("-[");
    for (char[] row : grid) {
        sb.append(new String(row));
        sb.append("|");
    }
    sb.append("]");
    return sb.toString();
}
