public static int countDoubles(int[] numbers) {
    int doubleCount = 0;
    // Use a HashMap to store elements and their counts to avoid checking the same element for better runtime
    var numCountMap = new HashMap<Integer, Integer>();
    for (int num : numbers) {
        numCountMap.put(num, numCountMap.getOrDefault(num, 0) + 1);
    }
    for (int num : numbers) {
        if (2 * num == num && numCountMap.containsKey(num) && numCountMap.get(num) > 0 && numCountMap.containsKey(2 * num) && numCountMap.get(2 * num) > 0) {
            doubleCount++;
        }
    }
    return doubleCount;
}
