import java.util.HashSet;
import java.util.Set;

public class MazeSolver {
    public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        // Validate input parameters
        if (n <= 0 || start == null || end == null || paths == null) {
            return "invalid input";
        }

        // Convert start and end coordinates to positions in the maze
        int startRow = start[0];
        int startCol = start[1];
        int endRow = end[0];
        int endCol = end[1];

        // Create a set to mark visited intersections to avoid loops
        Set<Integer> visited = new HashSet<>();

        // Function to check if a direction (up, down, left, right) is valid within the maze
        boolean isValidDirection(int x, int y, int[][] maze) {
            return x >= 0 && x < n && y >= 0 && y < n && maze[x][y] != 0;
        }

        // Depth-first search to determine if the end can be reached
        boolean canReachEnd = dfs(startRow, startCol, visited, paths);
        return canReachEnd ? "can be travelled" : "cannot be travelled";
    }

    private static boolean dfs(int x, int y, Set<Integer> visited, int[][] paths) {
        // If the current position is the end, return true
        if (x == endRow && y == endCol) {
            return true;
        }

        // Mark the current position as visited
        visited.add(x * n + y);

        // Try moving in all four directions
        for (int[] direction : new int[][]{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}) {
            int newX = x + direction[0];
            int newY = y + direction[1];

            // Check if the new position is valid and not visited
            if (isValidDirection(newX, newY, paths) && !visited.contains(newX * n + newY)) {
                // Recur to the new position
                if (dfs(newX, newY, visited, paths)) {
                    return true;
                }
            }
        }

        // Backtrack by removing the current position from the visited set
        visited.remove(x * n + y);
        return false;
    }
}
