import java.util.HashSet;
import java.util.Set;
public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    Set<Integer> visited = new HashSet<>();
    return findMazePaths(n, start, end, paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean findMazePaths(int n, int[] start, int[] end, int[][] paths, Set<Integer> visited) {
    if (start[0] == end[0] && start[1] == end[1]) {
        return true;
    }
    visited.add(start[0] * n + start[1]);
    if (start[0] - 1 >= 0 && !visited.contains((start[0] - 1) * n + start[1]) && findMazePaths(n, new int[]{start[0] - 1, start[1]}, end, paths, visited)) {
        return true;
    }
    if (start[0] + 1 < n && !visited.contains((start[0] + 1) * n + start[1]) && findMazePaths(n, new int[]{start[0] + 1, start[1]}, end, paths, visited)) {
        return true;
    }
    if (start[1] - 1 >= 0 && !visited.contains(start[0] * n + (start[1] - 1)) && findMazePaths(n, new int[]{start[0], start[1] - 1}, end, paths, visited)) {
        return true;
    }
    if (start[1] + 1 < n && !visited.contains(start[0] * n + (start[1] + 1)) && findMazePaths(n, new int[]{start[0], start[1] + 1}, end, paths, visited)) {
        return true;
    }
    return false;
}
