public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    boolean visited[] = new boolean[n];
    boolean isTravelable = DFS(start, end, paths, visited, 0);
    return isTravelable ? "can be travelled" : "cannot be travelled";
}

private static boolean DFS(int[] current, int[] end, int[][] paths, boolean[] visited, int step) {
    if (step == paths.length || isAtEnd(current, end)) {
        return true;
    }

    visited[current[0] * n + current[1]] = true;

    for (int[] path : paths) {
        if (!visited[path[0] * n + path[1]]) {
            boolean result = DFS(new int[]{path[0], path[1]}, end, paths, visited, step + 1);
            if (result) {
                visited[current[0] * n + current[1]] = false; // Backtrack
                return true;
            }
        }
    }

    visited[current[0] * n + current[1]] = false;
    return false;
}

private static boolean isAtEnd(int[] current, int[] end) {
    return current[0] == end[0] && current[1] == end[1];
}
