public static String appx(String word1, String word2) throws IllegalArgumentException {
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Both words must be non-null and non-empty");
    }

    int commonLetters = 0;
    Set<Character> set1 = word1.chars().mapToObj(c -> (char) c).collect(Collectors.toSet());
    Set<Character> set2 = word2.chars().mapToObj(c -> (char) c).collect(Collectors.toSet());

    for (char c : set1) {
        if (set2.contains(c)) {
            commonLetters++;
        }
    }

    int sumOfLengths = word1.length() + word2.length();
    double approximateValue = (double) commonLetters / sumOfLengths;
    String reducedFraction = "appx(" + word1 + ", " + word2 + ") = " + approximateValue;

    return reducedFraction;
}
