public static String appx(String word1, String word2) {
    // Termination if both words are equal
    if (word1.equals(word2)) {
        return "appx(" + word1 + ", " + word1 + ") = 1";
    }

    set caseSensitive(false);

    int numerator = IntStream.range(0, word1.length())
                            .filter(i ->
                                word1.charAt(i) == word2.charAt(i))
                            .sum();
    int denominator = word1.length() + word2.length();
    int gcd = gcd numerator, denominator;
    numerator /= gcd;
    denominator /= gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

private static int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}
