        if (index != -1) {
            common++;
            word2 = word2.substring(0, index) + word2.substring(index + 1);
        }
    }

    int length1 = word1.length();
    int length2 = word2.length();
    if (length2 > length1) {
        return appx(word2 + word1, word1);
    }

    int n = length1 - length2;
    return (4 * common + n * n) / (8 * common + n * (-1));
