public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null || (word1.length() == 0 && word2.length() == 0)) {
        throw new IllegalArgumentException("Both words must be non-null and non-empty.");
    }
    if (word1.length() == 0 || word2.length() == 0) {
        return word1.isEmpty() ? "0" : word2.isEmpty() ? "0" : "0/1";
    }

    int commonLetters = 0;
    for (int i = 0; i < word1.length() && i < word2.length(); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }

    int numerator = commonLetters;
    int denominator = word1.length() + word2.length() - commonLetters;

    // Simplify the fraction
    int gcd = greatestCommonDivisor(numerator, denominator);
    return String.format("appx(%s, %s) = %d/%d", word1, word2, numerator / gcd, denominator / gcd);
}

private static int greatestCommonDivisor(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
