import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

public class DateUtil {
    public static String convertDatesToWeekdays(String date) {
        if (date == null || date.length() != 10 || !date.matches("\\d{2} \\d{2} \\d{4}")) {
            throw new IllegalArgumentException("Date input must be in 'MM dd yyyy' format");
        }

        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("MM dd yyyy");
        try {
            LocalDate dateObject = LocalDate.parse(date, formatter);
            return dateObject.getDayOfWeek().name() + ", " + dateObject.getDayOfMonth() + ", " + dateObject.getYear() + " is a " + dateObject.getDayOfWeek().name();
        } catch (Exception e) {
            throw new RuntimeException("Error parsing or converting date string", e);
        }
    }

    public static void main(String[] args) {
        System.out.println(convertDatesToWeekdays("11 15 1997")); // November 15, 1997 is a Saturday
        System.out.println(convertDatesToWeekdays("01 01 2000")); // January 1, 2000 is a Saturday
        System.out.println(convertDatesToWeekdays("07 04 1998")); // July 4, 1998 is a Saturday
    }
}
