public class DateConverter {

    /**
     * Converts a date in the format "MM dd yyyy" to a weekday in words.
     * 
     * Example:
     * >>> convertDatesToWeekdays("11 15 1997")
     * "November 15, 1997 is a Saturday"
     * >>> convertDatesToWeekdays("01 01 2000")
     * "January 1, 2000 is a Saturday"
     * >>> convertDatesToWeekdays("07 04 1998")
     * "July 4, 1998 is a Saturday"
     * 
     * @param date the date in the format "MM dd yyyy"
     * @return a string representing the weekday of the date
     */
    public static String convertDatesToWeekdays(String date) {
        // Convert the date string to LocalDate object
        LocalDate dateObj = LocalDate.parse(date);

        // Use WeekDay.of() to get the weekday
        WeekDay weekday = dateObj.getDayOfWeek();

        // Get the weekday name in English
        String dayName = weekday.getName();

        // Construct and return the final string
        return date + " is a " + dayName;
    }
}
