    double highest5 = Arrays.stream(arr).sorted().skip(arr.length - arr.length / 20).average().orElseThrow(() -> new ArithmeticException("Failed to calculate average"));

    // Calculate the mean of the remaining elements after removing the lowest and highest 5%
    result = Arrays.stream(arr).filter(e -> e != lowest5 && e != highest5).average().orElseThrow(() -> new ArithmeticException("Failed to calculate average"));
}
return result;
