public class ArrayPairSumDivisibleByK {
    /**
     * Checks if the given array can be divided into n/2 pairs such that the sum of each pair is divisible by k.
     *
     * @param arr the input integer array
     * @param k the divisor
     * @return true if it is possible, false otherwise
     */
    public boolean canArrange(int[] arr, int k) {
        if (arr == null || arr.length % 2 != 0) {
            throw new IllegalArgumentException("Array must be non-null and have an even length.");
        }

        HashSet<Integer> remainderSet = new HashSet<>();
        for (int num : arr) {
            int remainder = num % k;
            if (remainderSet.contains(remainder)) {
                return false;
            }
            remainderSet.add(remainder);
        }

        return true;
    }
}
