public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0 || k == 0) {
        return false;
    }

    Map<Integer, Integer> remainders = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        int complementary = k - remainder;

        if (complementary == k) {
            if (remainders.containsKey((complementary / k) % k)) {
                return false;
            }
        } else {
            if (!remainders.containsKey(remainder)) {
                remainders.put(remainder, 1);
            } else {
                return false;
            }
        }
    }

    return true;
}
