import java.util.*;

class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        return dfs(0, adj, hasApple, 0);
    }

    private int dfs(int node, List<List<Integer>> adj, boolean[] hasApple, int parent) {
        int time = 0;
        for (int neighbor : adj.get(node)) {
            if (neighbor != parent) {
                int subTime = dfs(neighbor, adj, hasApple, node);
                if (subTime > 0 || hasApple[neighbor]) {
                    time += subTime + 2;
                }
            }
        }
        return time;
    }
}
