            if (!paths.contains(next)) {
                paths.add(next);
                pathTime += dfs(tree, paths, next, hasApple);
                paths.remove(paths.size() - 1);
            }
        }

        if ((hasApple[currentNode] && pathTime > 0) || pathTime > 0) {
            return pathTime + 2; // Return time to node 0 + time taken by the path
        }
        return pathTime;
