public class AppleCollector {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            int start = edge[0];
            int end = edge[1];
            graph.computeIfAbsent(start, k -> new ArrayList<>()).add(end);
            graph.computeIfAbsent(end, k -> new ArrayList<>()).add(start);
        }

        boolean[] visited = new boolean[n];
        List<Integer> apples = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (hasApple[i]) {
                apples.add(i);
            }
        }

        int cost = helper(0, graph, visited, apples, new int[]{0});
        return cost == Integer.MAX_VALUE ? 0 : cost;
    }

    private int helper(int node, Map<Integer, List<Integer>> graph, boolean[] visited, List<Integer> apples, int[] cost) {
        visited[node] = true;
        int totalCost = 0;
        boolean hasApple = false;
        List<Integer> neighbors = graph.getOrDefault(node, new ArrayList<>());
        for (int neighbor : neighbors) {
            if (!visited[neighbor]) {
                int nextCost = helper(neighbor, graph, visited, apples, cost);
                totalCost += nextCost;
                hasApple |= (nextCost != 0 || hasApple);
            }
        }
        if (hasApple && isDescendant(apples, node)) {
            cost[0] = totalCost + 2;
        }
        return totalCost + (hasApple ? 1 : 0);
    }

    private boolean isDescendant(List<Integer> apples, int node) {
        for (int apple : apples) {
            if (apple == node) {
                return true;
            }
        }
        return false;
    }
}
