import java.util.Arrays;

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    int avgSum = totalSum / nums.length;
    if (avgSum == 0) {
        return false; // A single element cannot be split into two equal arrays
    }

    int remainingSum = totalSum - avgSum;
    int mid = nums.length / 2;
    int sum = 0;

    // Check all possible sublist sums that could be the left part of the array
    for (int i = 0; i < mid; i++) {
        sum += nums[i];
        if (sum * 2 == remainingSum && checkSum(nums, memo, mid, i + 1)) {
            return true;
        }
    }

    // Check all possible sublist sums that could be the right part of the array
    for (int i = mid; i < nums.length; i++) {
        sum += nums[i];
        if (sum * 2 == remainingSum && checkSum(nums, memo, mid, i + 1)) {
            return true;
        }
    }

    return false;
}

private boolean checkSum(int[] nums, int[] memo, int mid, int start) {
    if (start >= mid) {
        return true;
    }

    if (memo[start] != -1) {
        return memo[start] == 1;
    }

    boolean found = false;
    int sum = 0;

    for (int i = start; i < mid; i++) {
        sum += nums[i];
        if (sum * 2 == (remainingSum - nums[start]) && checkSum(nums, memo, mid, i + 1)) {
            found = true;
            break;
        }
    }

    memo[start] = found ? 1 : 0;
    return found;
}
