public int uniqueMorseRepresentations(String[] words) {
    // Morse code for each letter of the alphabet
    List<String> morseCode = List.of(".", "-", ".-", "-.", "---", ".", "...", "-", "..-", "...-", "..", "-.....", "-....", ".", "..-.",
                                                     "-.", "..-", "....-", ".", "...", "-.", "-....", ".", "..-.",
                                                     "-.", ".-.", "---", ".", "...", "-.", "-....", ".", "..-.",
                                                     "-...", ".-.", "---", ".", "...", "-.", "-....", ".", "..-.",
                                                     "-...", ".-.", "---", ".", "...", "-.", "-....", ".", "..-.");

    // Convert each word to its Morse code and use a set to get unique codes
    Set<String> uniqueCodes = Arrays.stream(words).map(word -> word.chars().map(this::chrToMorse).collect(Collectors.joining()))
                                   .collect(Collectors.toSet());

    return uniqueCodes.size();
}

private String chrToMorse(int code) {
    return morseCode.get(code - 'a');    
