public boolean hasAllCodes(String s, int k) {
    return introduceAllKParts(s, k) == k;
}

private char[] introduceAllKParts(String s, int k) {
    if (s == null || s.length() < k) return new char[0];
    int charCount = 1 << k;
    char[] result = new char[charCount];
    if (s.charAt(0) != '0') result[0] = s.charAt(0);
    for (int i = 0; i < s.length() - k; i++) {
        int index = (s.charAt(i) - '0') * charCount + (s.charAt(i + k) - '0');
        result[index] = s.charAt(i + k);
    }
    return result;
}
