public boolean hasAllCodes(String s, int k) {
    int len = s.length(), max = (int) Math.pow(2, k);
    if (max > len) return false;

    boolean[] used = new boolean[max];
    for (int end = k - 1; end < len; end++) {
        int current = Integer.parseInt(s.substring(end - k + 1, end + 1), 2);
        if (used[current]) return false;
        used[current] = true;
    }

    for (boolean x: used) {
        if (!x) return false;
    }

    return true;
}
