public int minInsertions(String s) {
    int balance = 0; // to keep track of the current balance of brackets
    int insertions = 0; // to count the total number of insertions required
    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++; // increment balance if opening bracket is encountered
        } else {
            if (balance == 0) {
                // if closing bracket is encountered but balance is zero, it means we need one insertion
                // to balance the brackets, so we increment the insertions counter
                insertions++;
            }
            balance--; // decrement balance if closing bracket is encountered
            if (balance < 0) {
                // if balance goes negative after decrement, it means there are more closing brackets than opening brackets
                // in the remaining part of the string, so we need to insert extra opening brackets
                // to balance the brackets, so we decrement the insertions counter and increment the count of needed opening brackets
                // by as many times as we need extra opening brackets
                insertions++;
                balance++;
            }
        }
    }
    // add one more insertion if balance is positive (one extra opening bracket needed to balance the rest of the string)
    insertions += balance > 0 ? 1 : 0;
    return insertions;
}
