public int minOperations(int n) {
    // Calculate the target value to make all elements equal
    int target = (n * n + 1) >> 2;
    int operations = 0;

    // Iterate through the array and calculate the number of operations needed to make each element equal to target
    for (int i = 0; i < n; i++) {
        int value = 2 * i + 1;
        if (value != target) {
            operations += value - target >= 0 ? target - value : value - target; // Subtract 1 if value is greater than target, add 1 if value is less than target
        }
    }

    return operations;
}
