public int findMinFibonacciNumbers(int k) {
    // Initialize an array with the first two Fibonacci numbers
    int[] fib = new int[]{1, 1};
    // Generate Fibonacci numbers until one of them exceeds k
    while ( fib[fib.length - 1] <= k) {
        fib[fib.length] = fib[fib.length - 1] + fib[fib.length - 2];
    }
    // Initialize the result and list of used Fibonacci numbers
    int result = 0;
    ArrayList<Integer> used = new ArrayList<>();
    // Iterate through the Fibonacci numbers, starting from the last one to the first
    for (int i = fib.length - 1; i >= 0; i--) {
        // If the current Fibonacci number is less than or equal to k, add it to the result and used list
        if (fib[i] <= k) {
            result++;
            k -= fib[i];
            used.add(fib[i]);
        }
        // If the current Fibonacci number is greater than k, break the loop as no further Fibonacci numbers are needed
        if (fib[i] > k) break;
    }
    // Return the result
    return result;
}
