public int findMinFibonacciNumbers(int k) {
    // Base cases
    if (k == 1 || k == 2) return 1;
    if (k == 0) return 0;

    // Generate Fibonacci numbers up to k
    int[] fibArray = new int[k + 1];
    fibArray[0] = 0;
    fibArray[1] = 1;
    int fibSize = 2;

    while (fibArray[fibSize - 1] < k) {
        fibArray[fibSize] = fibArray[fibSize - 1] + fibArray[fibSize - 2];
        fibSize++;
    }

    // Find the minimum number of Fibonacci numbers
    int result = 0;
    while (k > 0) {
        while (fibArray[fibSize - 1] > k) {
            fibSize--;
        }
        result += 1;
        k -= fibArray[fibSize - 1];
    }

    return result;
}
