import java.util.Collections;
import java.util.Deque;
import java.util.HashSet;
import java.util.PriorityQueue;
import java.util.Set;

public class Solution {
    public int findMinFibonacciNumbers(int k) {
        Set<Integer> fibonacciSet = new HashSet<>();
        fibonacciSet.add(0);

        PriorityQueue<Integer> priorityQueue = new PriorityQueue<>();
        priorityQueue.offer(1);
        priorityQueue.offer(2);

        for (int i = 3; i < 1000; i++) {
            int nextFib = priorityQueue.poll() + priorityQueue.peek();
            if (nextFib > k) {
                break;
            }
            fibonacciSet.add(nextFib);
            priorityQueue.offer(nextFib);
        }

        Deque<Integer> deque = new LinkedList<>();
        while (k > 0) {
            if (fibonacciSet.contains(k)) {
                deque.offerLast(k);
                k = 0;
                break;
            }
            for (int fib : fibonacciSet) {
                if (k - fib > 0 && k - fib <= 1000) {
                    deque.offerLast(fib);
                    k -= fib;
                    break;
                }
            }
        }

        return deque.size();
    }
}
