public class StringManipulation {
    /**
     * Removes adjacent characters that are of the same case.
     * 
     * @param s The input string to be processed.
     * @return The processed string with adjacent characters of the same case removed.
     */
    public static String makeGood(String s) {
        Stack<Character> stack = new Stack<>();
        for (char c : s.toCharArray()) {
            if (stack.isEmpty() || (Math.abs(stack.peek() - c) == 32)) {
                stack.push(c);
            } else {
                stack.pop();
            }
        }
        StringBuilder result = new StringBuilder();
        while (!stack.isEmpty()) {
            result.insert(0, stack.pop());
        }
        return result.toString();
    }

    public static void main(String[] args) {
        System.out.println(makeGood("leEeetcode")); // "leetcode"
        System.out.println(makeGood("abBAcC"));  // ""
        System.out.println(makeGood("s"));      // "s"
    }
