public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxUnique = 0;
    TrieNode root = new TrieNode();
    Set<String> uniqueSubstrings = new HashSet<>();

    for (int i = 0; i < s.length(); i++) {
        String prefix = s.substring(0, i + 1);
        if (uniqueSubstrings.contains(prefix)) {
            removePrefix(root, prefix);
        } else {
            uniqueSubstrings.add(prefix);
            maxUnique++;
        }
        addPrefix(root, prefix);
    }

    return maxUnique;
}

private void addPrefix(TrieNode root, String prefix) {
    TrieNode current = root;
    for (char c : prefix.toCharArray()) {
        if (current.children[c - 'a'] == null) {
            current.children[c - 'a'] = new TrieNode();
        }
        current = current.children[c - 'a'];
    }
}

private void removePrefix(TrieNode root, String prefix) {
    TrieNode current = root;
    for (char c : prefix.toCharArray()) {
        current = current.children[c - 'a'];
    }
    current.isEnd = false;
}

private class TrieNode {
    TrieNode[] children = new TrieNode[26];
    boolean isEnd = false;
}
