    // Function to generate the lexicographically smallest string of length n and value k
    public String getSmallestString(int n, int k) {
        // Check if k is less than the minimum possible value for a string of length n
        if (k < n) {
            throw new IllegalArgumentException("k is too large for the given n");
        }
        StringBuilder smallestString = new StringBuilder();

        // Fill the string from the end with the largest possible characters
        for (int i = n - 1; i >= 0; i--) {
            int charValue = (k % 26) + 'a';
            smallestString.append((char) charValue);
            k -= charValue - 'a'; // Update k after each character is added
