public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("Both n and k must be positive integers.");
    }

    if (k < 26 * n) {
        return makeStringBases(n, k);
    } else {
        return makeStringArray();
    }
}

private String makeStringBases(int num, int sum) {
    String ans = "";
    int x = 0;
    while (num > 0) {
        int y = min(num - 1, sum / num);
        y = Math.max(y, 1);
        sum -= y * num;
        x += y;
        ans += (char) ('a' + (x - 1));
        num--;
    }
    return ans;
}

private String makeStringArray() {
    String[] per = {"a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m", "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z"};
    String[] arr = new String[n];
    int sum = arr.length * 26;
    int index = 0;
    while (sum > 0) {
        int y = min(arr.length - 1, sum / arr.length);
        y = Math.max(y, 1);
        sum -= y * arr.length;
        arr[index++] = per[y - 1];
    }
    String ans = "";
    for (int i = 0; i < n; i++) {
        ans += arr[i];
    }
    return ans;
}

private int min(int x, int y) {
    return x < y ? x : y;
}
