public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0; // The first and only passenger always sits in their own seat
    }
    double dp[][] = new double[n + 1][n + 1];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= i; j++) {
            if (j == i) {
                dp[i][j] = 1;
            } else {
                dp[i][j] = (i - 1) * dp[i - 1][j] / i;
            }
        }
    }
    return 1 - dp[n][n - 1];
}
