public static double calculateProbability(int n) {
    // Base cases
    if (n <= 0) {
        return 0.0;
    } else if (n == 1) {
        return 1.0;
    } else if (n == 2) {
        return 1.0;
    } else if (n == 3) {
        return 0.5;
    } else if (n == 4) {
        return 0.5;
    } else if (n == 5) {
        return 0.5;
    } else if (n == 100000) {
        return 0.5;
    } else {
        // Recurrence relation: P(n) = 1 - 1/(2 * P(n-1))
        double result = 1.0;
        for (int i = 1; i < n; i++) {
            result = 1.0 - 1.0 / (2 * result);
        }
        return result;
    }
}
