public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0; // If there are 1 or 0 passengers, the probability is 1 because the last passenger cannot sit in their own seat
    }
    // Use dynamic programming to calculate the probability
    double[] dp = new double[n + 1];
    dp[1] = 1.0; // If there is 1 passenger, the probability is 1 because the last passenger cannot sit in their own seat
    dp[2] = 0.5; // If there are 2 passengers, the probability is 0.5 because the second passenger can sit in their own seat or the first passenger can sit in the second passenger's seat
    for (int i = 3; i <= n; i++) {
        dp[i] = dp[i - 1] * 0.5; // Each additional passenger must move into one of the remaining seats, which is half the probability
    }
    return dp[n];
}
