import java.util.ArrayList;
import java.util.List;

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > 9) {
        return result;
    }

    int[] kidsToNext = new int[10];
    kidsToNext[0] = 1;
    kidsToNext[2] = 1;
    kidsToNext[4] = 1;
    kidsToNext[6] = 1;
    kidsToNext[8] = 1;
    kidsToNext[7] = 0;
    kidsToNext[9] = 0;

    for (int k = 0; k < kidsToNext.length; k++) {
        if (kidsToNext[k] == 1) {
            result.add(k);
        }
    }

    for (int num : result) {
        while (true) {
            if (num == high) {
                return result;
            }
            num = getNextNum(num);
        }
    }

    return result;
}

private static int getNextNum(int num) {
    char[] digits = String.valueOf(num).toCharArray();
    int n = digits.length;
    boolean foundNext = false;
    for (int i = n - 2; i >= 0; i--) {
        if (digits[i] == '9' || digits[i] == '0' || (i + 1 < n && digits[i + 1] == digits[i] + 2)) {
            let carry = (digits[i] == '0') ? 1 : 0;
            digits[i] = (digits[i] == '9' ? '0' : (digits[i] - 1)) + carry;
            for (int j = 0; j < i; j++) {
                digits[j] = '2';
            }
            break;
        } else if (digits[i] == '1' && (i + 1 < n && digits[i + 1] == '2' || i + 1 == n)) {
            foundNext = true;
            break;
        }
    }
    if (!foundNext) {
        digits[n - 1] += 1;
    }
    return Integer.parseInt(new String(digits));
}
