public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    int upperLimit = high + 1;
    int lowerLimit = Math.max(low, 0);

    // Check if 0 is a stepping number
    if (used(0)) {
        result.add(0);
    }

    // Build stepping numbers
    for (int current = lowerLimit; current < upperLimit; current++) {
        if (used(current)) {
            result.add(current);
        }
    }

    return result;
}

private static boolean used(int n) {
    if (n == 0) return true;

    int maxDigit = n % 10;
    n /= 10;

    while (n > 0) {
        int top = n % 10;
        if ((top == maxDigit + 1 || top == maxDigit - 1) && used(n / 10)) {
            return true;
        }
        n /= 10;
    }

    return false;
}
