import java.lang.Math;

public static int squarePermutations(int[] A) {
    if (A.length <= 1) return A.length; // Single element array is considered a square permutation

    int n = A.length;
    int[] left = new int[n];
    int[] right = new int[n];

    // Find the left and right indices where each element's square sum is a perfect square
    for (int i = 0; i < n; i++) {
        int leftSum = 0;
        for (int j = 0; j < i; j++) {
            leftSum += (A[j] * A[j]) % 4;
        }
        left[i] = 2 * (leftSum << 2);

        int rightSum = 0;
        for (int j = i + 1; j < n; j++) {
            rightSum += (A[j] * A[j]) % 4;
        }
        right[i] = 16 + 2 * (rightSum << 2);
    }

    int[] count = new int[16];
    // Calculate the count of square permutations
    for (int i = 0; i < n; i++) {
        int index = left[i] + right[i] - 32;
        count[index & 15]++;
    }

    int result = 1;
    for (int i = 0; i < 16; i++) {
        result = (result * count[i]) % (1000000007);
    }

    return result;
}
