private static void helper(int[] A, int index, Set<Integer> used, String prefix, Set<String> permutations) {
    if (prefix.length() == A.length) {
        permutations.add(prefix);
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used.contains(A[i] || prefix.length() > 0 && prefix.charAt(prefix.length() - 1) == A[i])) continue;
        used.add(A[i]);
        helper(A, i, used, prefix + A[i], permutations);
        used.remove(A[i]);
