import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n < 2) return n == 0 ? 1 : 0;

    List<List<Integer>> result = new ArrayList<>();
    boolean[] visited = new boolean[n];

    helper(A, 0, result, visited);

    return result.size();
}

private static void helper(int[] A, int currentIndex, List<List<Integer>> result, boolean[] visited) {
    if (currentIndex == A.length) {
        List<Integer> permutation = new ArrayList<>(Arrays.asList(A));
        result.add(permutation);
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (!visited[i]) {
            if (currentIndex == 0 || isPerfectSquare(A[currentIndex - 1], A[i])) {
                visited[i] = true;
                A[currentIndex] = A[i];
                helper(A, currentIndex + 1, result, visited);
                visited[i] = false;
                A[currentIndex] = 0; // Backtrack
            }
        }
    }
}

private static boolean isPerfectSquare(int x, int y) {
    int sum = x + y;
    int sqrt = (int) Math.sqrt(sum);
    return sqrt * sqrt == sum;
}
