import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class SquareArrayPermutations {
    public static int squarePermutations(int[] A) {
        Set<List<Integer>> validPermutations = new HashSet<>();

        // Filter out invalid pairs
        for (int i = 0; i < A.length - 1; i++) {
            if (!isPerfectSquare(A[i] + A[i + 1])) {
                A[i] = -A[i]; // Mark as invalid
            }
        }

        // Calculate permutations of valid pairs
        calculatePermutations(A, validPermutations);

        return validPermutations.size();
    }

    private static boolean isPerfectSquare(int x) {
        int sqrt = (int) Math.sqrt(x);
        return sqrt * sqrt == x;
    }

    private static void calculatePermutations(int[] A, Set<List<Integer>> validPermutations) {
        if (A.length % 2 != 0) {
            return; // Odd length array, cannot form a permutation
        }

        List<Integer> permutations = IntStream.range(0, A.length / 2)
                .mapToObj(i -> A[i])
                .collect(Collectors.toList());

        SubsetCalculator subsetCalculator = new SubsetCalculator(permutations);
        List<Integer> res = new ArrayList<>();
        subsetCalculator.permute("", res);

        for (List<Integer> perm : res) {
            int[] permArray = perm.stream().mapToInt(i -> i).toArray();
            boolean isValid = true;
            for (int i = 0; i < permArray.length - 1; i++) {
                if (!isPerfectSquare(permArray[i] + permArray[i + 1])) {
                    isValid = false;
                    break;
                }
            }
            if (isValid) {
                int[] validPerm = new int[A.length];
                int pos = 0;
                for (int i = 0; i < permArray.length / 2; i++) {
                    validPerm[2 * i] = permArray[i];
                    validPerm[2 * i + 1] = -permArray[i];
                }
                validPermutations.add(new ArrayList<>(Arrays.asList(validPerm)));
            }
        }
    }
}

class SubsetCalculator {
    private List<Integer> originalNumbers;
    private Set<List<Integer>> validPermutations;

    public SubsetCalculator(List<Integer> originalNumbers) {
        this.originalNumbers = originalNumbers;
        this.validPermutations = new HashSet<>();
    }

    public void permute(String prefix, List<Integer> result) {
        if (originalNumbers.isEmpty()) {
            validPermutations.add(new ArrayList<>(result));
            return;
        }

        for (int i = 0; i < originalNumbers.size(); i++) {
            result.add(originalNumbers.get(i));
            permute(prefix + originalNumbers.get(i), result);
            result.remove(result.size() - 1);
        }
    }
}
