    for (int i = 0; i < n; i++) {
        int width = right[i] - left[i] - 1;
        int height = heights[i];
        area[i] = width * height;
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, area[i]);
    }

    return maxArea;
