public static int findSmallestInteger(int n) {
    // Convert the input integer to a string, sort it, and then convert back to an integer
    char[] digits = String.valueOf(n).toCharArray();
    Arrays.sort(digits);

    // Iterate through the sorted digits
    for (int i = digits.length - 1; i > 0; i--) {
        // Find the first index where the current digit is greater than the digit immediately before it
        if (digits[i] > digits[i - 1]) {
            // Swap these two digits
            char temp = digits[i];
            digits[i] = digits[i - 1];
            digits[i - 1] = temp;
            // Sort the digits from this index to the end in ascending order
            Arrays.sort(digits, i, digits.length);
            // Form the rearranged integer
            return Integer.parseInt(new String(digits));
        }
    }
    // If the input integer is in descending order, no valid rearrangement is possible
    return -1;
