public class SymmetricNumberFinder {
    public static List<String> centerSymmetricNumbers(int n) {
        List<String> centerSymmetricNumbers = new ArrayList<>();
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        String pattern;
        int period = (int) Math.pow(10, n / 2);
        if (n % 2 == 0) {
            pattern = "999999999";
        } else {
            pattern = "100000000";
        }

        for (int i = 0; i < period; i++) {
            centerSymmetricNumbers.add(padWithZeroes(pattern, n));
            if (n % 2 != 0) {
                centerSymmetricNumbers.add(padWithZeroes(pattern.substring(1), n));
            }
        }

        return centerSymmetricNumbers;
    }

    private static String padWithZeroes(String pattern, int length) {
        int paddingLength = length - pattern.length();
        StringBuffer sb = new StringBuffer();
        for (int i = 0; i < paddingLength; i++) {
            sb.append("0");
        }
        return sb.append(pattern).toString();
    }

    // Check function to verify the correctness of the generated function.
    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Expected: ["11","69","88","96"]
        System.out.println(centerSymmetricNumbers(1)); // Expected: ["0","1","8"]
    }
}
