private static final int[] primes = {2, 3, 5};
private static int[] memo = new int[n];

public static int findNthUglyNumber(final int n) {
    if (memo[n - 1] != 0) {
        return memo[n - 1];
    }

    var i = 0;
    var j = 0;
    var k = 0;
    int res = 1;

    while (i < primes.length && j < primes.length && k < primes.length && res <= n) {
        if (primes[i] <= primes[j] && primes[i] <= primes[k]) {
            res = primes[i];
            increment(i);
        } else if (primes[j] <= primes[i] && primes[j] <= primes[k]) {
            res = primes[j];
            increment(j);
        } else {
            res = primes[k];
            increment(k);
        }
    }

    memo[n - 1] = res;
    return res;
}

private static void increment(int num) {
    for (int i = num; i < primes.length; i++) {
        if (memo[primes[i] - 1] == 0) {
            memo[primes[i] - 1] = memo[num] * primes[i];
            return;
        }
