		throw new IllegalArgumentException("n must be greater than 0");
	}

	int[] uglyNumbers = new int[n];
	uglyNumbers[0] = 1;
	int i = 0; // Index for 2
	int j = 0; // Index for 3
	int k = 0; // Index for 5

	for (int i = 1; i < n; i++) {
		int nextUgly = Math.min(uglyNumbers[i-1]*2, uglyNumbers[j]*3, uglyNumbers[k]*5);
		uglyNumbers[i] = nextUgly;
		if (nextUgly == uglyNumbers[i-1]*2) i++;
		if (nextUgly == uglyNumbers[j]*3) j++;
		if (nextUgly == uglyNumbers[k]*5) k++;
	}

	return uglyNumbers[n-1];
