        uglyNumbers[count] = Math.min(uglyNumbers[i] * 2, Math.min(uglyNumbers[j] * 3, uglyNumbers[k] * 5));
        // Move the pointer for the chosen number
        if (uglyNumbers[count] == uglyNumbers[i] * 2) i++;
        if (uglyNumbers[count] == uglyNumbers[j] * 3) j++;
        if (uglyNumbers[count] == uglyNumbers[k] * 5) k++;
