import java.util.ArrayList;
import java.util.List;

public class LexicalOrder {

    public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            helper(i, result, n);
        }
        return result;
    }

    private static void helper(int start, List<Integer> result, int n) {
        if (start > n) {
            return;
        }
        result.add(start);
        for (int i = 0; i <= 9; i++) {
            if (start * 10 + i <= n) {
                helper(start * 10 + i, result, n);
            }
        }
    }

    // Example check function
    public static void main(String[] args) {
        System.out.println(lexicalOrder(13)); // Output: [1,10,11,12,13,2,3,4,5,6,7,8,9]
    }
}
