import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> lexicalOrder(int n) {
        return lexicalOrder(1, n);
    }

    private static List<Integer> lexicalOrder(int start, int end) {
        List<Integer> result = new ArrayList<>();
        if (start > end) {
            return result;
        }

        result.add(start);
        int nextDigit = start + 1;
        while (nextDigit <= end && Character.digit(Character.forDigit(nextDigit, 10), 10) <= Character.digit(Character.forDigit(nextDigit - 1, 10), 10)) { // make sure continuing the current digit is lexicographically larger than the current digit
            result.addAll(lexicalOrder(nextDigit, end));
            nextDigit++;
        }

        return result;
    }
}
