public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];

    // There is one way to represent 0 as: 0 perfect squares
    dp[0] = 0;

    // Build the DP table for each number from 1 to n
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;

        // Try all numbers j from 1 to i that are their square root to find the minimum
        for (int j = 1; j <= i; j++) {
            int square = j * j;
            if (square > i) {
                break;
            }
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }

    return dp[n];
}
