public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    final int max = (int) Math.sqrt(n);
    int[] dp = new int[n + 1];

    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;

    for (int i = 1; i <= max; i++) {
        int square = i * i;
        for (int j = square; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - square] + 1);
        }
    }

    return dp[n];
}
