import java.util.HashSet;

public static int minPerfectSquareSum(int n) {
    HashSet<Integer> squares = new HashSet<>();
    for (int i = 1; i * i <= n; i++) {
        squares.add(i * i);
    }
    return minSum(n, squares);
}

private static int minSum(int n, HashSet<Integer> squares) {
    if (n == 0) return 0;
    if (squares.contains(n)) return 1;
    int min = Integer.MAX_VALUE;
    for (int square : squares) {
        if (n >= square) {
            min = Math.min(min, 1 + minSum(n - square, squares));
        }
    }
    return min;
}
