public static String reverseWords(String s) {
    s = s.trim(); // Remove leading/trailing spaces
    StringBuilder result = new StringBuilder();
    String[] words = s.split("\\s+"); // Split the string into words
    for (int i = words.length - 1; i >= 0; i--) {
        if (i != 0) result.append(" "); // Add space between words
        result.append(revWord(words[i])); // Reverse the word and append to result
    }
    return result.toString();
}

private static String revWord(String word) {
    char[] reversedChars = word.toCharArray();
    int left = 0, right = reversedChars.length - 1;
    while (left < right) {
        char temp = reversedChars[left];
        reversedChars[left] = reversedChars[right];
        reversedChars[right] = temp;
        left++;
        right--;
    }
    return new String(reversedChars);
}
